//! 🧾️ Resident encoder receipt payout keeps original Source owners through settlement.
#[macro_export]
macro_rules! native_encode_receipt_payout {()=>{
/// 🧳️ Exclusively retains the original encoder state and result until its paid handoff settles.
pub struct NativeEncodeReceiptPayout<'a>{state:&'a mut super::NativeEncodeEffectState,failure:&'a mut Option<super::NativeEncodeEffectFailure>,local:&'a mut crate::RetainedCloneProgress,grant:crate::RetainedCloneGrant,source:crate::OriginalSourceTurnIdentity,binding:semio_framework_value_control_contract::OriginalWorkBindingIdentity,next:crate::RetainedCloneProgress,completion:Option<semio_framework_value_control_contract::OriginalConstructionCompletion>,replacement:Option<semio_framework_value_control_contract::OriginalConstructionCompletion>,final_payout:Option<semio_framework_value_control_contract::OriginalConstructionActionIdentity>,final_work:Option<semio_framework_value_control_contract::OriginalWorkActionIdentity>,final_progress:Option<crate::RetainedCloneProgress>,physical_finished:bool,done:bool}
impl<'a> NativeEncodeReceiptPayout<'a>{
 /// 🪢️ Binds the actual pending Source, Work, physical owner and caller result slots.
 pub fn begin(control:&mut NativeEncodeControl<'_>,source:crate::OriginalSourceTurnWitness<'_>,state:&'a mut super::NativeEncodeEffectState,failure:&'a mut Option<super::NativeEncodeEffectFailure>,grant:crate::RetainedCloneGrant,local:&'a mut crate::RetainedCloneProgress)->Result<Self,ValueError>{
  if control.source_turn!=Some(source.identity()){return Err(invalid("encoder receipt Source changed"))}let allocation=control.scoped_allocation.as_deref_mut().ok_or_else(||invalid("encoder allocation Source absent"))?;let work=control.action.recipient.as_deref_mut().ok_or_else(||invalid("encoder Work Source absent"))?;let physical=control.construction.as_deref_mut().ok_or_else(||invalid("encoder construction Source absent"))?;crate::native_receiving::span::progress::validate_source_authorities(source,allocation,work,physical)?;let allocation_identity=allocation.identity();let physical_identity=physical.identity();let binding=semio_framework_value_control_contract::OriginalWorkBorrow::new(&mut control.action).binding_identity()?;let span=control.recorded_span.as_deref_mut().ok_or_else(||invalid("encoder span Source absent"))?;let checkpoint=control.recorded_checkpoint.as_deref_mut().ok_or_else(||invalid("encoder checkpoint Source absent"))?;if span.source_turn()!=Some(source.identity())||checkpoint.source_turn()!=Some(source.identity()){return Err(invalid("encoder recorded Source changed"))}span.validate_context()?;checkpoint.validate_context()?;let span_identity=span.identity();let checkpoint_identity=checkpoint.identity();let ledger_identity=control.ledger.as_ref().ok_or_else(||invalid("encoder ledger absent"))?.identity();if state.request.as_ref().is_none_or(|request|!request.matches_payout_authorities(source.identity(),ledger_identity,allocation_identity,binding,physical_identity,span_identity,checkpoint_identity))||state.producer_settled||!state.producer_ready||state.local_binding!=Some((grant,*local))||state.allocation.is_some(){return Err(invalid("encoder receipt request changed"))}let selected=state.selection.ok_or_else(||invalid("encoder receipt selection absent"))?;let settlement=state.settlement.as_ref().ok_or_else(||invalid("encoder receipt settlement absent"))?;if !settlement.receipt_refused(){return Err(invalid("encoder receipt has no recorded refusal"))}let next=local.checked_add(settlement.submitted_progress().ok_or_else(||invalid("encoder receipt progress absent"))?)?;let owner=failure.as_ref().ok_or_else(||invalid("encoder failure owner absent"))?;if (!state.physical.fits(selected)&&owner.physical_invariant.is_some())||(!next.fits(grant)&&owner.local.is_some())||(selected.maximum_capacity_bytes==0&&state.actual.is_some()&&owner.capacity_invariant.is_some())||(state.outcome.as_ref().is_some_and(super::allocation_failed)&&owner.allocation.is_some()){return Err(invalid("encoder receipt result is occupied"))}control.finish_refused_effect_work(&mut state.settlement)?;Ok(Self{state,failure,local,grant,source:source.identity(),binding,next,completion:None,replacement:None,final_payout:None,final_work:None,final_progress:None,physical_finished:false,done:false})
 }
 /// ⏸️ Suspends only before any payout owner has moved, leaving the original receipt resident.
 pub fn suspend(&mut self)->bool{if self.done||self.completion.is_some()||self.replacement.is_some()||self.final_payout.is_some()||self.state.settlement.as_ref().is_none_or(|settlement|!settlement.receipt_refused()){return false}self.done=true;true}
 fn port_matches(&self,port:&semio_framework_value_control_contract::OriginalConstructionLoan<'_>,effect:&semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->bool{!self.done&&port.source_turn()==Some(self.source)&&self.binding.matches_effect(effect)}
 /// 📥️ Stages the actual original refused receipt into this same resident payout.
 pub fn stage_original(&mut self,port:&semio_framework_value_control_contract::OriginalConstructionLoan<'_>,payout:&semio_framework_value_control_contract::OriginalConstructionAction,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<crate::RetainedCloneProgress>,ValueError>{if !self.port_matches(port,effect){return crate::RetainedWorkOutcome{result:Err(invalid("encoder receipt authorities changed")),work:0}}match self.state.settlement.as_mut(){Some(settlement)=>settlement.stage_refused_receipt(port,payout,&mut self.completion,effect),None=>crate::RetainedWorkOutcome{result:Err(invalid("original settlement is absent")),work:0}}}
 /// 🔁️ Restages only the exact original completion against its separately published refusal.
 pub fn retry_original(&mut self,port:&semio_framework_value_control_contract::OriginalConstructionLoan<'_>,refusal:&semio_framework_value_control_contract::OriginalConstructionCompletion,payout:&semio_framework_value_control_contract::OriginalConstructionAction,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<crate::RetainedCloneProgress>,ValueError>{if !self.port_matches(port,effect){return crate::RetainedWorkOutcome{result:Err(invalid("encoder receipt retry authorities changed")),work:0}}let witness=match port.witness(payout){Ok(witness)=>witness,Err(error)=>return crate::RetainedWorkOutcome{result:Err(error),work:0}};let turn=port.restage_completion(&mut self.completion,&mut self.replacement,refusal,&witness,effect);if matches!(&turn.result,Ok(Some(_))){self.completion=self.replacement.take()}turn}
 /// 🔓️ Publishes only after the exact original payout and Work proof settle.
 pub fn publish_original(&mut self,control:&mut NativeEncodeControl<'_>,source:crate::OriginalSourceTurnWitness<'_>,payout:&mut semio_framework_value_control_contract::OriginalConstructionAction,proof:&semio_framework_value_control_contract::OriginalWorkActionProof)->Result<bool,ValueError>{if source.identity()!=self.source||control.source_turn!=Some(self.source){return Err(invalid("encoder receipt Source changed"))}control.with_original_effect_work_and_construction(|work,port|{if work.binding_identity()?!=self.binding||port.source_turn()!=Some(self.source){return Err(invalid("encoder receipt authorities changed"))}port.publish_completion(self.completion.as_mut().ok_or_else(||invalid("encoder completion absent"))?,payout,work,proof)})}
 /// 📥️ Stages the published original completion into the same retained encoder cause.
 pub fn stage_receipt(&mut self,port:&semio_framework_value_control_contract::OriginalConstructionLoan<'_>,payout:&semio_framework_value_control_contract::OriginalConstructionAction,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<crate::RetainedCloneProgress>,ValueError>{if !self.port_matches(port,effect){return crate::RetainedWorkOutcome{result:Err(invalid("encoder receipt authorities changed")),work:0}}match self.state.settlement.as_mut(){Some(settlement)=>settlement.stage_published_receipt(port,&mut self.completion,payout,effect),None=>crate::RetainedWorkOutcome{result:Err(invalid("original settlement is absent")),work:0}}}
 /// 🔁️ Retries the same retained receipt using an independently published payout refusal.
 pub fn retry_receipt(&mut self,port:&semio_framework_value_control_contract::OriginalConstructionLoan<'_>,refusal:&semio_framework_value_control_contract::OriginalConstructionCompletion,payout:&semio_framework_value_control_contract::OriginalConstructionAction,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<crate::RetainedCloneProgress>,ValueError>{if !self.port_matches(port,effect){return crate::RetainedWorkOutcome{result:Err(invalid("encoder receipt retry authorities changed")),work:0}}match self.state.settlement.as_mut(){Some(settlement)=>settlement.retry_published_receipt(port,refusal,payout,effect),None=>crate::RetainedWorkOutcome{result:Err(invalid("original settlement is absent")),work:0}}}
 /// 🔓️ Publishes the receipt cause after the matching same-Source payout settles.
 pub fn publish_receipt(&mut self,control:&mut NativeEncodeControl<'_>,source:crate::OriginalSourceTurnWitness<'_>,payout:&semio_framework_value_control_contract::OriginalConstructionAction,proof:&semio_framework_value_control_contract::OriginalWorkActionProof)->Result<bool,ValueError>{if source.identity()!=self.source||control.source_turn!=Some(self.source)||semio_framework_value_control_contract::OriginalWorkBorrow::new(&mut control.action).binding_identity()?!=self.binding{return Err(invalid("encoder receipt Source changed"))}control.publish_refused_effect_receipt(&mut self.state.settlement,payout,proof)}
 /// 👁️ Reports the retained original settlement without exposing its failure owner.
 pub fn settlement_status(&self)->super::NativeEncodeEffectSettlementStatus{super::native_encode_effect_settlement_status(&self.state.settlement)}
 /// 📏️ Prices the final resident result handoff under the same original Source.
 pub fn transfer_demand()->Result<RetirementDemand,ValueError>{NativeEncodeEffectSettlement::failure_transfer_demand()}
 /// 📤️ Moves the original settlement into its still-exclusively-borrowed failure slot.
 pub fn stage_transfer(&mut self,port:&semio_framework_value_control_contract::OriginalConstructionLoan<'_>,payout:&semio_framework_value_control_contract::OriginalConstructionAction,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<crate::RetainedCloneProgress>,ValueError>{if !self.port_matches(port,effect)||self.final_payout.is_some(){return crate::RetainedWorkOutcome{result:Err(invalid("encoder failure payout changed")),work:0}}let work=effect.work_identity().action_identity();let turn=NativeEncodeEffectSettlement::finish_into_paid(&mut self.state.settlement,self.failure.as_mut().expect("original failure retained"),port,payout,effect);if let Ok(Some(progress))=&turn.result{self.final_payout=Some(payout.identity());self.final_work=Some(work);self.final_progress=Some(*progress)}turn}
 /// 📏️ Prices retry metadata without reposting the already-performed failure transfer.
 pub fn retry_transfer_demand()->RetirementDemand{RetirementDemand{copy_bytes:std::mem::size_of::<Option<semio_framework_value_control_contract::OriginalConstructionActionIdentity>>()+std::mem::size_of::<Option<semio_framework_value_control_contract::OriginalWorkActionIdentity>>()+std::mem::size_of::<Option<crate::RetainedCloneProgress>>(),depth:1,..Default::default()}}
 /// 🔁️ Retries only after retaining the exact independently published payout refusal.
 pub fn retry_transfer(&mut self,port:&semio_framework_value_control_contract::OriginalConstructionLoan<'_>,refusal:&semio_framework_value_control_contract::OriginalConstructionCompletion,payout:&semio_framework_value_control_contract::OriginalConstructionAction,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<crate::RetainedCloneProgress>,ValueError>{use semio_framework_value_control_contract as core;let fail=|error|core::RetainedWorkOutcome{result:Err(error),work:0};if self.done||self.physical_finished||!self.port_matches(port,effect)||refusal.action_identity()!=self.final_payout||refusal.status()!=Some(core::OriginalConstructionAcceptStatus::Refused)||refusal.work_binding()!=Some(self.binding){return fail(invalid("encoder transfer refusal changed"))}match port.validates_completion(refusal){Ok(true)=>{},Ok(false)=>return fail(invalid("encoder transfer refusal issuer changed")),Err(error)=>return fail(error)}let demand=Self::retry_transfer_demand();let witness=match port.witness(payout){Ok(witness)=>witness,Err(error)=>return fail(error)};if witness.phase()!=core::OriginalConstructionPhase::Granted||witness.demand()!=demand||witness.grant()!=Some(effect.grant())||witness.work_binding()!=self.binding||effect.actual().is_some(){return fail(invalid("encoder transfer retry changed"))}match effect.remaining_work_units(){Ok(0)=>return core::RetainedWorkOutcome{result:Ok(None),work:0},Err(error)=>return fail(error),Ok(_)=>{}}if !core::retained_clone_grant_admits(effect.grant(),demand){return core::RetainedWorkOutcome{result:Ok(None),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return core::RetainedWorkOutcome{result:Err(invalid("encoder transfer retry exceeded Work")),work:1},Err(error)=>return fail(error)}let progress=crate::RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()};self.final_payout=Some(payout.identity());self.final_work=Some(effect.work_identity().action_identity());self.final_progress=Some(progress);core::RetainedWorkOutcome{result:Ok(Some(progress)),work:1}}
 /// ✅️ Returns the exact final payout and Work owners before exposing the retained result.
 pub fn acknowledge(&mut self,control:&mut NativeEncodeControl<'_>,source:crate::OriginalSourceTurnWitness<'_>,payout:&mut Option<semio_framework_value_control_contract::OriginalConstructionAction>,proof:&mut Option<semio_framework_value_control_contract::OriginalWorkActionProof>,work_action:&mut Option<semio_framework_value_control_contract::OriginalWorkActionIdentity>)->Result<bool,ValueError>{use semio_framework_value_control_contract as core;if self.done||source.identity()!=self.source||control.source_turn!=Some(self.source){return Err(invalid("encoder final Source changed"))}let ready=control.with_original_effect_work_and_construction(|work,port|{if work.binding_identity()?!=self.binding||port.source_turn()!=Some(self.source){return Err(invalid("encoder final authorities changed"))}let actual_proof=proof.as_ref().ok_or_else(||invalid("encoder payout proof absent"))?;if Some(actual_proof.action_identity())!=self.final_work||*work_action!=self.final_work||actual_proof.actual_work()==0||!work.validates(actual_proof,actual_proof.actual_work())?{return Err(invalid("encoder payout Work changed"))}if !self.physical_finished{let action=payout.as_ref().ok_or_else(||invalid("encoder payout action absent"))?;if Some(action.identity())!=self.final_payout||!port.validates_action(action)?||action.work_binding()!=self.binding||action.progress()!=self.final_progress||action.actual().is_some(){return Err(invalid("encoder payout action changed"))}match action.recorded_accept_status(){None|Some(core::OriginalConstructionAcceptStatus::Refused)=>return Ok(false),Some(core::OriginalConstructionAcceptStatus::Accepted)=>{}}port.finish_accepted(payout)?;self.physical_finished=true}work.finish(proof,work_action)?;Ok(true)})?;if !ready{return Ok(false)}let owner=self.failure.as_mut().expect("original failure retained");let selected=self.state.selection.expect("original selection retained");if !self.state.physical.fits(selected){owner.physical_invariant=Some(invalid("native encode physical effect exceeded its selected demand"))}if selected.maximum_capacity_bytes==0&&self.state.actual.is_some(){owner.capacity_invariant=Some(invalid("unallocated native effect invoked an allocator"))}if !self.next.fits(self.grant){owner.local=Some(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native encode effect exceeded its local grant"))}if self.state.outcome.as_ref().is_some_and(super::allocation_failed){owner.allocation=self.state.outcome.take()}*self.local=self.next;self.state.producer_settled=true;self.done=true;Ok(true)}
}
impl Drop for NativeEncodeReceiptPayout<'_>{fn drop(&mut self){assert!(std::thread::panicking()||self.done,"original encoder receipt payout remains resident")}}
}}
